body.script:
//

/* ===== UTILITY ===== */
function fmt(d){
  if(!d)return '';
  var p=d.split('-');
  return p[2]+'.'+p[1]+'.'+p[0].slice(2);
}

function getWAPhone(){
  var v = document.getElementById('centerPhone').value.trim().replace(/[^0-9]/g,'');
  if(v.length >= 10) return '88' + v.replace(/^88/,'');
  return '8801938327130';
}

function loadHtml2Canvas(cb){
  if(window.html2canvas){ cb(); return; }
  var s = document.createElement('script');
  s.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
  s.onload = cb;
  document.head.appendChild(s);
}

function htmlToImage(html, fileName){
  loadHtml2Canvas(function(){
    var iframe = document.createElement('iframe');
    iframe.style.cssText = 'position:fixed;top:-9999px;left:-9999px;width:794px;height:1123px;border:none;visibility:hidden;';
    document.body.appendChild(iframe);
    iframe.contentDocument.open();
    iframe.contentDocument.write(html);
    iframe.contentDocument.close();
    setTimeout(function(){
      var body = iframe.contentDocument.body;
      var actualH = Math.max(body.scrollHeight, body.offsetHeight, 1123);
      iframe.style.height = actualH + 'px';
      setTimeout(function(){
        html2canvas(body, {
          scale: 2, useCORS: true, allowTaint: true,
          width: 794, height: actualH,
          windowWidth: 794, windowHeight: actualH,
          scrollX: 0, scrollY: 0, backgroundColor: '#ffffff'
        }).then(function(canvas){
          document.body.removeChild(iframe);
          var link = document.createElement('a');
          link.download = (fileName||'document').replace(/\s+/g,'_') + '.png';
          link.href = canvas.toDataURL('image/png', 1.0);
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        }).catch(function(){
          document.body.removeChild(iframe);
          alert('Image তৈরি করা যায়নি। PDF ব্যবহার করুন।');
        });
      }, 200);
    }, 800);
  });
}

function openPDFTab(html, fileName, patPhone, centerPhoneRaw, waMsg){
  var safeFile = (fileName || 'document').replace(/\s+/g,'_');
  try {
    var w = window.open('','_blank');
    if(w){ w.document.open(); w.document.write(html); w.document.close(); }
    else { alert('পপআপ ব্লক হয়েছে। Browser-এ Allow করুন।'); }
  } catch(e){ alert('পপআপ ব্লক হয়েছে। Browser-এ Allow করুন।'); }
  if(!waMsg) return;
  var encodedMsg = encodeURIComponent(waMsg);
  var delay = 1200;
  if(patPhone){
    var pRaw = patPhone.replace(/[^0-9]/g,'');
    if(pRaw.length >= 10){
      var pNum = '88' + pRaw.replace(/^88/,'');
      setTimeout(function(){
        window.open('https://api.whatsapp.com/send?phone='+pNum+'&text='+encodedMsg,'_blank');
      }, delay);
      delay += 800;
    }
  }
  if(centerPhoneRaw){
    var cRaw = centerPhoneRaw.replace(/[^0-9]/g,'');
    if(cRaw.length >= 10){
      var cNum = '88' + cRaw.replace(/^88/,'');
      setTimeout(function(){
        window.open('https://api.whatsapp.com/send?phone='+cNum+'&text='+encodedMsg,'_blank');
      }, delay);
    }
  }
}

