};

/* ===== DIAGNOSIS STEP SYSTEM ===== */
var diagStepOrder = ['bodnazar','jadu','jinn','waswasa'];
var diagStepIndex = 0;
var diagAllResults = {};
var diagPatientInfo = {};

/* ===== DIAGNOSIS FOR — SIMPLE DROPDOWN ===== */
var _diagAgeSelected = '';

function onDiagForChange(){
  var forVal = document.getElementById('diagFor').value;
  var ageSel = document.getElementById('diagAgeSelect');
  if(!ageSel) return;
  ageSel.innerHTML = '<option value="">-- সিলেক্ট --</option>';
  if(forVal === 'self'){
    ageSel.innerHTML += '<option value="adult">&#x1F9D1; ১২+ বছর</option>';
    ageSel.value = 'adult';
    _applyDiagAge('adult');
  } else if(forVal === 'other'){
    ageSel.innerHTML += '<option value="infant">&#x1F37C; ০ – ২ বছর</option>';
    ageSel.innerHTML += '<option value="child">&#x1F9D2; ২ – ১২ বছর</option>';
    ageSel.innerHTML += '<option value="adult">&#x1F9D1; ১২+ বছর</option>';
  } else {
    document.getElementById('diagPersonType').value = '';
    document.getElementById('diagChildAge').value   = '';
    document.getElementById('diagAge').value        = '';
  }
}

function onDiagAgeSelectChange(){
  var val = document.getElementById('diagAgeSelect').value;
  _diagAgeSelected = val;
  if(val) _applyDiagAge(val);
  else {
    document.getElementById('diagPersonType').value = '';
    document.getElementById('diagChildAge').value   = '';
    document.getElementById('diagAge').value        = '';
  }
}

function _applyDiagAge(group){
  if(group === 'infant'){
    document.getElementById('diagPersonType').value = 'child';
    document.getElementById('diagChildAge').value   = 'infant';
    document.getElementById('diagAge').value        = 'infant';
  } else if(group === 'child'){
    document.getElementById('diagPersonType').value = 'child';
    document.getElementById('diagChildAge').value   = 'child';
    document.getElementById('diagAge').value        = 'child';
  } else {
    document.getElementById('diagPersonType').value = 'adult';
    document.getElementById('diagChildAge').value   = '';
    document.getElementById('diagAge').value        = '';
  }
}

function selectDiagAge(group){ _diagAgeSelected = group; _applyDiagAge(group); }

function startDiagnosis(){
  var name    = (document.getElementById('diagName')||{}).value.trim();
  var phone   = (document.getElementById('diagPhone')||{}).value.trim();
  var diagFor = (document.getElementById('diagFor')||{}).value;
  if(!name){ alert('নাম লিখুন'); document.getElementById('diagName').focus(); return; }
  if(!phone){ alert('WhatsApp নম্বর লিখুন'); document.getElementById('diagPhone').focus(); return; }
  if(!diagFor){ alert('ডায়াগনোসিস কার জন্য সিলেক্ট করুন'); return; }
  var ageSelEl = document.getElementById('diagAgeSelect');
  if(ageSelEl && ageSelEl.value) _diagAgeSelected = ageSelEl.value;
  if(!_diagAgeSelected){ alert('বয়স গ্রুপ সিলেক্ট করুন'); return; }

  /* Hidden compat fields আপডেট করো */
  var cNameEl = document.getElementById('cName');
  var cPhEl   = document.getElementById('cPhone');
  if(cNameEl) cNameEl.value = name;
  if(cPhEl)   cPhEl.value   = phone;

  var age = '';
  var personType = 'adult';
  if(_diagAgeSelected === 'adult'){ personType = 'adult'; age = ''; }
  else if(_diagAgeSelected === 'infant'){ personType = 'child'; age = 'infant'; }
  else if(_diagAgeSelected === 'child'){ personType = 'child'; age = 'child'; }

  diagPatientInfo = { name:name, phone:phone, diagFor:diagFor, age:age, personType:personType };
  diagAllResults = {};
  diagStepIndex = 0;
  alreadyCheckedTexts = [];

  if(personType === 'child'){
    diagStepOrder = ['bachcha'];
  } else {
    diagStepOrder = ['bodnazar','jadu','jinn','waswasa'];
  }
  openNextDiagStep();
}

function openNextDiagStep(){
  if(diagStepIndex >= diagStepOrder.length){
    showFinalCombinedResult();
    return;
  }
  var type = diagStepOrder[diagStepIndex];
  openDiagnosis(type);
}

var currentDiagType = 'bodnazar';
var diagSelected = {};

var bnNum = ['','১','২','৩','৪','৫','৬','৭','৮','৯','১০','১১','১২','১৩','১৪','১৫','১৬','১৭','১৮','১৯','২০','২১','২২','২৩','২৪','২৫','২৬','২৭','২৮','২৯','৩০','৩১','৩২','৩৩','৩৪','৩৫','৩৬','৩৭','৩৮','৩৯','৪০'];

function openDiagnosis(type){
  currentDiagType = type || 'bodnazar';
  diagSelected = {};
  var d = diagData[currentDiagType];
  document.getElementById('popupTitle').textContent = d.title;
  document.getElementById('popupHeader').style.background = d.color;
  document.getElementById('diagCount').innerHTML = '&#x2714; ০টি সমস্যা নির্বাচিত';

  var list = document.getElementById('chkList');
  list.innerHTML = '';

  if(d.groups){
    var idx = 0;
    var groupsToShow = d.groups;
    if(currentDiagType === 'bachcha'){
      groupsToShow = d.groups.filter(function(grp){
        if(_diagAgeSelected === 'infant'){
          return grp.label.indexOf('০–২') > -1 || grp.label.indexOf('0–2') > -1 || grp.label.indexOf('০-২') > -1;
        } else if(_diagAgeSelected === 'child'){
          return grp.label.indexOf('২–১২') > -1 || grp.label.indexOf('2–12') > -1 || grp.label.indexOf('২-১২') > -1;
        }
        return true;
      });
    }
    groupsToShow.forEach(function(grp){
      var lbl = document.createElement('div');
      lbl.style.cssText = 'font-size:12px;font-weight:700;color:'+d.color+';background:#e8f5eb;padding:7px 10px;border-radius:6px;margin:10px 0 6px;';
      lbl.innerHTML = grp.label;
      list.appendChild(lbl);
      grp.items.forEach(function(item){
        var txt = (item && item.text) ? item.text : item;
        var wt  = (item && item.w) ? item.w : 1;
        idx++;
        if(!isAlreadyChecked(item)){
          list.appendChild(makeChkItem(idx, txt, d.color, wt));
        } else {
          diagSelected[idx] = true;
        }
      });
    });
  } else {
    var visibleIdx = 0;
    d.items.forEach(function(item, i){
      var txt = (item && item.text) ? item.text : item;
      var wt  = (item && item.w) ? item.w : 1;
      if(!isAlreadyChecked(item)){
        visibleIdx++;
        list.appendChild(makeChkItem(visibleIdx, txt, d.color, wt));
        if(!window._idxMap) window._idxMap = {};
        window._idxMap[visibleIdx] = i+1;
      } else {
        diagSelected[i+1] = true;
      }
    });
  }

  var stepInfo = document.getElementById('popupStepInfo');
  if(stepInfo && diagStepOrder && diagStepOrder.length > 1){
    var stepNum = diagStepIndex + 1;
    var totalSteps = diagStepOrder.length;
    stepInfo.textContent = 'ধাপ ' + stepNum + '/' + totalSteps + ' — সমস্যাগুলো মার্ক করুন';
  } else if(stepInfo){
    stepInfo.textContent = 'আপনার যে সমস্যাগুলো আছে সেগুলো মার্ক করুন';
  }

  var nextBtn = document.getElementById('popupNextBtn');
  if(nextBtn && diagStepOrder){
    var isLast = (diagStepIndex >= diagStepOrder.length - 1);
    if(isLast){
      nextBtn.innerHTML = '<i class="fas fa-check-circle"></i> ডায়াগনোসিস সম্পন্ন করুন';
    } else {
      nextBtn.innerHTML = '<i class="fas fa-arrow-right"></i> পরবর্তী ধাপ';
    }
  }

  var popup = document.getElementById('diagPopup');
  popup.classList.add('open');
  popup.scrollTop = 0;
  document.body.style.overflow = 'hidden';
}

function makeChkItem(n, txt, color, wt){
  var wBadge = '';
  if(wt===3) wBadge = '<span style="font-size:9px;background:#c0392b;color:#fff;border-radius:3px;padding:1px 4px;margin-left:4px;vertical-align:middle;flex-shrink:0;">Strong</span>';
  else if(wt===2) wBadge = '<span style="font-size:9px;background:#e67e22;color:#fff;border-radius:3px;padding:1px 4px;margin-left:4px;vertical-align:middle;flex-shrink:0;">Medium</span>';
  else wBadge = '<span style="font-size:9px;background:#7f8c8d;color:#fff;border-radius:3px;padding:1px 4px;margin-left:4px;vertical-align:middle;flex-shrink:0;">Weak</span>';
  var div = document.createElement('div');
  div.className = 'chk-item';
  div.id = 'di'+n;
  div.setAttribute('onclick','toggleChk('+n+')');
  div.innerHTML =
    '<div class="chk-box" id="dib'+n+'"></div>'+
    '<div class="chk-num">'+bnNum[n]+'.</div>'+
    '<div class="chk-text" style="flex:1;">'+txt+wBadge+'</div>';
  return div;
}

var alreadyCheckedTexts = [];

function recordCheckedTexts(type){
  var d = diagData[type];
  var keys = Object.keys(diagSelected).map(Number);
  keys.forEach(function(n){
    var txt = getItemTextByType(type, n);
    if(txt && alreadyCheckedTexts.indexOf(txt) === -1){
      alreadyCheckedTexts.push(txt);
    }
  });
}

function isAlreadyChecked(item){
  var txt = (item && item.text) ? item.text : item;
  return alreadyCheckedTexts.indexOf(txt) > -1;
}

function closeDiagnosis(){
  document.getElementById('diagPopup').classList.remove('open');
  document.body.style.overflow = '';
}

function toggleChk(n){
  var item = document.getElementById('di'+n);
  var box  = document.getElementById('dib'+n);
  if(!item || !box) return;
  if(diagSelected[n]){
    delete diagSelected[n];
    item.classList.remove('checked');
    box.innerHTML = '';
  } else {
    diagSelected[n] = true;
    item.classList.add('checked');
    box.innerHTML = '&#x2714;';
  }
  updateCount();
}

function updateCount(){
  var visible = document.querySelectorAll('#chkList .chk-item.checked').length;
  document.getElementById('diagCount').innerHTML = '&#x2714; '+(bnNum[visible]||visible)+'টি সমস্যা নির্বাচিত';
}

function clearAll(){
  var keys = Object.keys(diagSelected);
  keys.forEach(function(n){
    var item = document.getElementById('di'+n);
    var box  = document.getElementById('dib'+n);
    if(item) item.classList.remove('checked');
    if(box)  box.innerHTML = '';
  });
  diagSelected = {};
  updateCount();
}

function getItemText(n){
  var items = getAllItems(currentDiagType);
  var item = items[n-1];
  return item ? (item.text||item) : '';
}

/* ── getAllItems: groups বা items থেকে flat array বের করে ── */
function getAllItems(type){
  var d = diagData[type];
  if(!d) return [];
  if(d.items) return d.items;
  if(d.groups){
    var all = [];
    d.groups.forEach(function(g){ g.items.forEach(function(it){ all.push(it); }); });
    return all;
  }
  return [];
}

function getWeightedScore(type, keys){
  var items = getAllItems(type);
  if(!items.length) return {score:0, max:0};
  var d = diagData[type];
  var max = d.maxScore || items.reduce(function(s,it){ return s+(it.w||1); },0);
  var score = 0;
  keys.forEach(function(n){
    var item = items[n-1];
    if(item) score += (item.w||1);
  });
  return {score:score, max:max};
}

