   ============================================================ */
var diagRules = {
  bodnazar: {
    anchors: [2,5,12,13,20,21],
    clusters: [
      {items:[1,9],   bonus:2, label:'মনোযোগহীনতা + হাই উঠা'},
      {items:[7,8],   bonus:2, label:'শরীর দুর্বলতা + চুল পড়া'},
      {items:[12,13], bonus:3, label:'অদৃশ্য জ্বর + তেলাওয়াতে হাই'},
      {items:[20,21], bonus:3, label:'প্রশংসার পর + সাফল্যের পর সমস্যা (ইসাবাহ)'},
      {items:[22,23], bonus:2, label:'সোশ্যাল মিডিয়া + বিশেষ মানুষ (হাসাদ সংকেত)'}
    ],
    minScore: 6,
