function evaluateDiagnosis(type, keys){
  var rules = diagRules[type];
  if(!rules) return {level:'none', label:'', clusters:[], anchorFound:false, score:0, pct:0};
  var ws = getWeightedScore(type, keys);
  var score = ws.score;
  var pct = ws.max > 0 ? Math.round((score/ws.max)*100) : 0;
  var anchorFound = rules.anchors.some(function(a){ return keys.indexOf(a) > -1; });
  var nonShared = keys.filter(function(k){ return rules.sharedOnly.indexOf(k) === -1; });
  var onlyShared = (nonShared.length === 0 && keys.length > 0);
  var matchedClusters = [];
  var clusterBonus = 0;
  rules.clusters.forEach(function(cl){
    var allMatch = cl.items.every(function(i){ return keys.indexOf(i) > -1; });
    if(allMatch){ matchedClusters.push(cl.label); clusterBonus += cl.bonus; }
  });
  var effectiveScore = score + clusterBonus;
  var level, label, color, advice;
  if(onlyShared){
    level='shared'; label='&#x26A0;&#xFE0F; অনিশ্চিত'; color='#7f8c8d';
    advice='শুধু সাধারণ উপসর্গ পাওয়া গেছে যা একাধিক কারণে হতে পারে। এটি নিশ্চিত করে '+getDiagLabel(type)+' বলা যাচ্ছে না।';
  } else if(!anchorFound || effectiveScore < rules.minScore){
    level='weak'; label='&#x1F535; দুর্বল সংকেত'; color='#2980b9';
    advice='কিছু লক্ষণ পাওয়া গেছে তবে নির্ণায়ক (Anchor) লক্ষণ নেই বা সংখ্যা যথেষ্ট নয়। এই মুহূর্তে '+getDiagLabel(type)+' নিশ্চিত বলা যাচ্ছে না। আরও পর্যবেক্ষণ দরকার।';
  } else if(anchorFound && effectiveScore >= rules.minScore && matchedClusters.length === 0){
    level='probable'; label='&#x1F7E1; সম্ভাবনা আছে'; color='#e67e22';
    advice=getDiagLabel(type)+'-এর সম্ভাবনা আছে। একজন রাকির সাথে পরামর্শ করুন এবং নিয়মিত রুকইয়াহ শুরু করুন।';
  } else if(anchorFound && matchedClusters.length >= 1 && effectiveScore >= rules.minScore + 3){
    level='confirmed'; label='&#x1F534; নিশ্চিত সম্ভাবনা'; color='#c0392b';
    advice='একাধিক নির্ণায়ক লক্ষণ ও ক্লাস্টার পাওয়া গেছে। '+getDiagLabel(type)+'-এর শক্তিশালী সম্ভাবনা আছে। দ্রুত একজন অভিজ্ঞ রাকির সাথে যোগাযোগ করুন।';
  } else {
    level='probable'; label='&#x1F7E1; সম্ভাবনা আছে'; color='#e67e22';
    advice=getDiagLabel(type)+'-এর সম্ভাবনা আছে। একজন রাকির সাথে পরামর্শ করুন এবং নিয়মিত রুকইয়াহ শুরু করুন।';
  }
  return {level:level, label:label, color:color, advice:advice, clusters:matchedClusters,
          anchorFound:anchorFound, score:effectiveScore, rawScore:score, pct:pct,
          subtypes:detectSubtypes(type, keys)};
}

function detectSubtypes(type, keys){
  var rules = diagRules[type];
  if(!rules || !rules.subtypes || keys.length === 0) return [];
  var matched = [];
  rules.subtypes.forEach(function(st){
    var count = st.indicators.filter(function(i){ return keys.indexOf(i) > -1; }).length;
    if(count >= st.minIndicators){
      matched.push({key:st.key, label:st.label, desc:st.desc, color:st.color, matchCount:count, total:st.indicators.length});
    }
  });
  matched.sort(function(a,b){ return b.matchCount - a.matchCount; });
  return matched;
}

function getDiagLabel(type){
  var labels = {bodnazar:'বদনজর', jadu:'জাদু', jinn:'জিন', waswasa:'ওয়াসওয়াসা', bachcha:'বাচ্চাদের সমস্যা'};
  return labels[type]||type;
}

function getDiagColor(key){
  var colors = {bodnazar:'#5c3a1a', jadu:'#2d1a5c', jinn:'#1a3a5c', waswasa:'#4a1a5c'};
  return colors[key]||'#1a5c3a';
}

function sendDiagnosis(){
  var keys = Object.keys(diagSelected).map(Number).sort(function(a,b){return a-b;});
  if(keys.length===0){alert('অন্তত একটি সমস্যা মার্ক করুন।');return;}
  var d    = diagData[currentDiagType];
  var name = diagPatientInfo.name || '';
  var phone= diagPatientInfo.phone || '';
  var m = '';
  m += d.title + ' রিপোর্ট\n';
  m += '━━━━━━━━━━━━━━━━━━━━\n';
  m += '&#x1F3E2; *প্রতিষ্ঠান:* Ruqyah Haven\n';
  if(name)  m += '&#x1F464; *নাম:* ' + name + '\n';
  if(phone) m += '&#x1F4F1; *ফোন:* ' + phone + '\n';
  m += '━━━━━━━━━━━━━━━━━━━━\n';
  m += '*চিহ্নিত সমস্যাসমূহ (' + keys.length + 'টি):*\n\n';
  keys.forEach(function(n){
    var txt = getItemTextByType(currentDiagType, n);
    m += '&#x2705; ' + bnNum[n] + '. ' + txt + '\n';
  });
  m += '━━━━━━━━━━━━━━━━━━━━\n';
  diagAllResults[currentDiagType] = { keys: keys, d: d, msg: m };
  recordCheckedTexts(currentDiagType);
  closeDiagnosis();
  diagStepIndex++;
  openNextDiagStep();
}

function sendResultWA(btn){
  var encoded = btn.getAttribute('data-msg');
  var m = decodeURIComponent(encoded);
  m += '\n&#x1F932; اللهم اشفه وعافه — আল্লাহুম্মাশফিহি ওয়া আফিহি।';
  window.open('https://api.whatsapp.com/send?phone='+getWAPhone()+'&text='+encodeURIComponent(m),'_blank');
}

function closeResult(){
  document.getElementById('resultOverlay').classList.remove('open');
  document.body.style.overflow = '';
}

function getItemTextByType(type, n){
  var d = diagData[type];
  if(!d) return '';
  /* bachcha: বয়স অনুযায়ী filter */
  if(type === 'bachcha' && d.groups){
    var groupsToUse = d.groups.filter(function(grp){
      if(_diagAgeSelected === 'infant'){
        return grp.label.indexOf('০–২') > -1 || grp.label.indexOf('0–2') > -1 || grp.label.indexOf('০-২') > -1;
      } else if(_diagAgeSelected === 'child'){
        return grp.label.indexOf('২–১২') > -1 || grp.label.indexOf('2–12') > -1 || grp.label.indexOf('২-১২') > -1;
      }
      return true;
    });
    var idx=0;
    for(var g=0;g<groupsToUse.length;g++){
      for(var i=0;i<groupsToUse[g].items.length;i++){
        idx++;
        if(idx===n){ var it=groupsToUse[g].items[i]; return it?(it.text||it):''; }
      }
    }
    return '';
  }
  /* সব অন্য type: getAllItems ব্যবহার করো */
  var items = getAllItems(type);
  var item = items[n-1];
  return item ? (item.text||item) : '';
}

function showFinalCombinedResult(){
  var info = diagPatientInfo;
