  var diagEmoji  = {bodnazar:'&#x1F441;&#xFE0F;', jadu:'&#x1FA84;', jinn:'&#x1F47B;', waswasa:'&#x1F9E0;', bachcha:'&#x1F476;'};
  var diagLabel  = {bodnazar:'বদনজর', jadu:'জাদু', jinn:'জিন', waswasa:'ওয়াসওয়াসা', bachcha:'বাচ্চাদের'};
