  html += '<div style="font-size:12px;font-weight:700;color:#1a5c3a;margin-bottom:8px;text-transform:uppercase;">&#x1F464; রোগীর তথ্য</div>';
  html += '<div style="font-size:13px;color:#333;line-height:1.8;">';
  html += '&#x1F4CC; নাম: <strong>'+info.name+'</strong><br>';
  html += '&#x1F4F1; নম্বর: <strong>'+info.phone+'</strong><br>';
  if(info.age) html += '&#x1F382; বয়স: <strong>'+(info.age==='infant'?'০–২ বছর':info.age==='child'?'২–১২ বছর':info.age+' বছর')+'</strong><br>';
  html += '&#x1F4DD; ডায়াগনোসিস: <strong>'+(info.diagFor==='self'?'নিজের জন্য':'অন্যের জন্য')+'</strong>';
  html += '</div></div>';
  var fullMsg = '&#x1F4CB; *সম্পূর্ণ ডায়াগনোসিস রিপোর্ট*\n';
  fullMsg += '&#x1F464; নাম: *'+info.name+'* | &#x1F4F1; '+info.phone+'\n';
  if(info.age) fullMsg += '&#x1F382; বয়স: '+(info.age==='infant'?'০–২ বছর':info.age==='child'?'২–১২ বছর':info.age+' বছর')+'\n';
  fullMsg += '&#x1F4C5; তারিখ: '+dateStr+'\n';
  fullMsg += '━━━━━━━━━━━━━━━━━━━━\n\n';
  var totalSymptoms = 0;
  var evalResults = {};
  diagStepOrder.forEach(function(type){
    var res = diagAllResults[type];
    var keys = res ? res.keys : [];
    totalSymptoms += keys.length;
    evalResults[type] = evaluateDiagnosis(type, keys);
  });
  html += '<div style="margin-bottom:12px;">';
  html += '<div style="font-size:12px;font-weight:700;color:#1a5c3a;text-transform:uppercase;margin-bottom:8px;">&#x1F4CA; ডায়াগনোসিস বিশ্লেষণ</div>';
  var hasConfirmed = false;
  var hasProbable  = false;
  var topAdvice    = [];
  diagStepOrder.forEach(function(type){
    var res   = diagAllResults[type];
    var ev    = evalResults[type];
    var color = diagColors[type]||'#1a5c3a';
    var emoji = diagEmoji[type]||'&#x1F50D;';
    var label = diagLabel[type]||type;
    var keys  = res ? res.keys : [];
    if(ev.level==='confirmed') hasConfirmed = true;
    if(ev.level==='probable')  hasProbable  = true;
    if(ev.level==='confirmed'||ev.level==='probable') topAdvice.push({label:label, ev:ev, color:color, emoji:emoji});
    html += '<div style="background:#fff;border:2px solid '+(ev.level==='confirmed'?'#c0392b':ev.level==='probable'?'#e67e22':ev.level==='weak'?'#2980b9':'#ccc')+';border-radius:10px;padding:10px 12px;margin-bottom:8px;">';
    html += '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">';
    html += '<span style="font-size:13px;font-weight:700;color:'+color+';">'+emoji+' '+label+'</span>';
    html += '<span style="font-size:11px;font-weight:700;color:#fff;background:'+(ev.level==='confirmed'?'#c0392b':ev.level==='probable'?'#e67e22':ev.level==='weak'?'#2980b9':'#95a5a6')+';border-radius:12px;padding:2px 9px;">'+ev.label+'</span>';
    html += '</div>';
    var barColor = ev.level==='confirmed'?'#c0392b':ev.level==='probable'?'#e67e22':ev.level==='weak'?'#2980b9':'#95a5a6';
    html += '<div style="background:#f0f0f0;border-radius:4px;height:7px;overflow:hidden;margin-bottom:5px;">';
    html += '<div style="background:'+barColor+';width:'+ev.pct+'%;height:100%;border-radius:4px;"></div>';
    html += '</div>';
    html += '<div style="font-size:11px;color:#666;">স্কোর: '+ev.rawScore+' পয়েন্ট | লক্ষণ: '+keys.length+'টি | '+ev.pct+'%</div>';
    if(ev.clusters && ev.clusters.length > 0){
      html += '<div style="margin-top:6px;">';
      ev.clusters.forEach(function(cl){
        html += '<div style="font-size:10px;background:#fff3e0;color:#e65100;border-radius:4px;padding:2px 7px;margin-top:3px;display:inline-block;margin-right:4px;">&#x1F517; '+cl+'</div>';
      });
      html += '</div>';
    }
    if(ev.subtypes && ev.subtypes.length > 0 && (ev.level==='confirmed'||ev.level==='probable')){
      html += '<div style="margin-top:8px;border-top:1px dashed #ddd;padding-top:7px;">';
      html += '<div style="font-size:10px;font-weight:700;color:#555;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:5px;">&#x1F50E; সম্ভাব্য প্রকার</div>';
      ev.subtypes.forEach(function(st, idx){
        var opacity = idx === 0 ? '1' : '0.75';
        html += '<div style="background:#f9f9f9;border-left:3px solid '+st.color+';border-radius:0 6px 6px 0;padding:6px 10px;margin-bottom:5px;opacity:'+opacity+';">';
        html += '<div style="font-size:12px;font-weight:700;color:'+st.color+';margin-bottom:2px;">'+st.label+'</div>';
        html += '<div style="font-size:11px;color:#555;line-height:1.5;">'+st.desc+'</div>';
        html += '<div style="font-size:10px;color:#999;margin-top:3px;">'+st.matchCount+'টি সূচক মিলেছে</div>';
        html += '</div>';
      });
      html += '</div>';
    }
    if(!ev.anchorFound && keys.length > 0){
      html += '<div style="font-size:10px;color:#999;margin-top:5px;">&#x26A0;&#xFE0F; নির্ণায়ক লক্ষণ (Anchor) পাওয়া যায়নি</div>';
    }
    html += '</div>';
    fullMsg += emoji+' *'+label+'* — '+ev.label+'\n';
    if(ev.subtypes && ev.subtypes.length > 0 && (ev.level==='confirmed'||ev.level==='probable')){
      fullMsg += '   &#x1F50E; সম্ভাব্য প্রকার: '+ev.subtypes[0].label+'\n';
    }
    if(keys.length > 0){
      var fmItems = getAllItems(type);
      keys.forEach(function(n,i){
        var d2 = diagData[type];
        var item2 = fmItems[n-1];
        var txt2 = item2 ? (item2.text||item2) : getItemTextByType(type, n);
        fullMsg += '  '+(i+1)+'. '+txt2+'\n';
      });
    }
    fullMsg += '\n';
  });
  html += '</div>';
  html += '<div style="background:#fff8e1;border:1px solid #f9a825;border-radius:10px;padding:12px 14px;margin-bottom:12px;">';
  html += '<div style="font-size:12px;font-weight:700;color:#e65100;margin-bottom:8px;">&#x1F932; রাকির পরামর্শ</div>';
  if(topAdvice.length === 0){
    html += '<div style="font-size:13px;color:#333;line-height:1.7;">আপনার চিহ্নিত লক্ষণগুলো থেকে কোনো নির্দিষ্ট রুহানি সমস্যার শক্তিশালী ইঙ্গিত পাওয়া যাচ্ছে না। নিয়মিত সকাল-সন্ধ্যার আযকার, কুরআন তিলাওয়াত এবং পাঁচ ওয়াক্ত নামাজ অব্যাহত রাখুন। সমস্যা অব্যাহত থাকলে একজন অভিজ্ঞ রাকির পরামর্শ নিন।</div>';
  } else {
    topAdvice.forEach(function(ta){
      html += '<div style="border-left:3px solid '+ta.color+';padding-left:10px;margin-bottom:8px;">';
      html += '<div style="font-size:12px;font-weight:700;color:'+ta.color+';margin-bottom:3px;">'+ta.emoji+' '+ta.label+'</div>';
      html += '<div style="font-size:12px;color:#333;line-height:1.6;">'+ta.ev.advice+'</div>';
      if(ta.ev.clusters && ta.ev.clusters.length > 0){
        html += '<div style="font-size:11px;color:#888;margin-top:4px;">সক্রিয় ক্লাস্টার: '+ta.ev.clusters.join(' | ')+'</div>';
      }
      html += '</div>';
    });
    if(hasConfirmed){
      html += '<div style="background:#fdecea;border-radius:6px;padding:8px 10px;margin-top:6px;font-size:12px;color:#c0392b;font-weight:700;">&#x26A1; দ্রুত একজন অভিজ্ঞ রাকির সাথে সশরীরে যোগাযোগ করুন। আল্লাহ সুবহানাহু ওয়া তাআলা শিফা দান করুন। আমীন।</div>';
    }
  }
  html += '</div>';
  html += '<div style="font-size:12px;font-weight:700;color:#555;text-transform:uppercase;margin-bottom:8px;">&#x1F4CB; বিস্তারিত লক্ষণ তালিকা</div>';
  diagStepOrder.forEach(function(type){
    var res   = diagAllResults[type];
    var ev    = evalResults[type];
    var color = diagColors[type]||'#1a5c3a';
    var emoji = diagEmoji[type]||'&#x1F50D;';
    var label = diagLabel[type]||type;
    var keys  = res ? res.keys : [];
    if(keys.length === 0) return;
    var d = diagData[type];
    var allItemsFlat = getAllItems(type);
    html += '<div style="border-radius:9px;overflow:hidden;margin-bottom:8px;border:1px solid #e0e0e0;">';
    html += '<div style="background:'+color+';color:#fff;padding:8px 12px;font-size:13px;font-weight:700;">'+emoji+' '+label+'</div>';
    html += '<div style="background:#fff;padding:6px 10px;">';
    keys.forEach(function(n,i){
      var item = allItemsFlat[n-1];
      var txt  = item ? (item.text||item) : getItemTextByType(type,n);
      var wt   = item ? (item.w||1) : 1;
      var dot  = wt===3?'&#x1F534;':wt===2?'&#x1F7E0;':'&#x1F7E1;';
      var isAnchor = diagRules[type] && diagRules[type].anchors && diagRules[type].anchors.indexOf(n) > -1;
      html += '<div style="padding:4px 0;border-bottom:1px solid #f5f5f5;font-size:11px;color:#333;display:flex;gap:5px;align-items:flex-start;">';
      html += '<span style="color:'+color+';font-weight:700;min-width:16px;">'+(i+1)+'.</span>';
      html += '<span style="flex:1;">'+(isAnchor?'<strong>':'')+txt+(isAnchor?'</strong>':'')+'</span>';
      html += '<span>'+dot+'</span>';
      if(isAnchor) html += '<span style="font-size:9px;background:'+color+';color:#fff;border-radius:3px;padding:1px 4px;flex-shrink:0;">Anchor</span>';
      html += '</div>';
    });
    html += '</div></div>';
  });
  fullMsg += '━━━━━━━━━━━━━━━━━━━━\n';
  fullMsg += '&#x1F522; মোট লক্ষণ: *'+totalSymptoms+'টি*\n';
  fullMsg += '&#x1F932; اللهم اشفه وعافه — আল্লাহুম্মাশফিহি ওয়া আফিহি।';
  html += '<div style="background:#fff3e0;border:1.5px solid #ff9800;border-radius:10px;padding:10px 13px;margin-bottom:12px;">';
  html += '<div style="font-size:11px;font-weight:700;color:#e65100;margin-bottom:4px;">&#x26A0;&#xFE0F; গুরুত্বপূর্ণ</div>';
  html += '<div style="font-size:11px;color:#444;line-height:1.7;">এটি ইসলামিক রুকইয়াহ পদ্ধতিতে পরিচালিত সম্ভাবনামূলক ডায়াগনোসিস — মেডিকেল ডায়াগনোসিস নয়। প্রতিটি লক্ষণের মেডিকেল কারণ আগে বাতিল করুন। নিশ্চিতকরণের জন্য ইফেক্ট ডায়াগনোসিস করুন এবং অভিজ্ঞ রাকির পরামর্শ নিন।</div>';
  html += '</div>';
  /* ইফেক্ট ডায়াগনোসিস বাটন */
  var hasEff = diagStepOrder.some(function(type){
    var res = diagAllResults[type];
    var ev  = evaluateDiagnosis(type, res ? res.keys : []);
    return ev.level === 'confirmed' || ev.level === 'probable';
  });
  if(hasEff){
    html += '<div style="background:#e8f0ff;border:1.5px solid #3a5cc0;border-radius:10px;padding:12px 14px;margin-bottom:10px;">';
    html += '<div style="font-size:13px;font-weight:700;color:#1a3a8c;margin-bottom:5px;">&#x1F3AF; ইফেক্ট ডায়াগনোসিস করুন</div>';
    html += '<div style="font-size:12px;color:#444;line-height:1.6;margin-bottom:10px;">সিম্পটম ডায়াগনোসিসের ফলাফল ১০০% নিশ্চিত করতে নির্দিষ্ট আয়াত পড়ুন এবং ইফেক্ট রিপোর্ট করুন।</div>';
    html += '<button onclick="closeResult();startEffectDiagnosis();" style="width:100%;padding:12px;background:#1a3a8c;color:#fff;border:none;border-radius:9px;font-size:14px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;font-family:Arial,sans-serif;" type="button"><i class="fas fa-flask"></i> ইফেক্ট ডায়াগনোসিস শুরু করুন</button>';
    html += '</div>';
  }
  html += '<button class="result-wa-btn" onclick="sendResultWA(this)" data-msg="'+encodeURIComponent(fullMsg)+'"><i class="fab fa-whatsapp"></i> সম্পূর্ণ রিপোর্ট WhatsApp-এ পাঠাও</button>';
  html += '<button class="result-next-btn" onclick="downloadFullDiagPDF()" style="background:#1a5c3a;margin-top:8px;"><i class="fas fa-file-pdf"></i> সম্পূর্ণ রিপোর্ট PDF ডাউনলোড করুন</button>';
  html += '<button class="result-close-btn" onclick="closeResult()">বন্ধ করুন</button>';
  body.innerHTML = html;
  document.getElementById('resultOverlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function downloadFullDiagPDF(imageMode){
