  var today = new Date();
  var dateStr = String(today.getDate()).padStart(2,'0')+'.'+String(today.getMonth()+1).padStart(2,'0')+'.'+String(today.getFullYear()).slice(2);
  var diagColors2 = {bodnazar:'#5c3a1a', jadu:'#2d1a5c', jinn:'#1a3a5c', waswasa:'#4a1a5c', bachcha:'#1a5c4a'};
  var diagLabel2  = {bodnazar:'বদনজর', jadu:'জাদু', jinn:'জিন', waswasa:'ওয়াসওয়াসা', bachcha:'বাচ্চাদের'};
  var allRows = '';
  var totalCount = 0;
  diagStepOrder.forEach(function(type){
    var res = diagAllResults[type];
    var color = diagColors2[type]||'#1a5c3a';
    var label = diagLabel2[type]||type;
    var count = res ? res.keys.length : 0;
    totalCount += count;
    allRows += '<tr><td colspan="2" style="background:'+color+';color:#fff;padding:7px 10px;font-size:12px;font-weight:700;">'+label+' ডায়াগনোসিস — '+count+'টি লক্ষণ</td></tr>';
    if(!res || res.keys.length === 0){
      allRows += '<tr><td colspan="2" style="padding:6px 10px;font-size:12px;color:#888;border:1px solid #ccc;">কোনো লক্ষণ চিহ্নিত হয়নি।</td></tr>';
    } else {
      var pdfItems = getAllItems(type);
