  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>সম্পূর্ণ ডায়াগনোসিস রিপোর্ট</title>'
    +'<style>*{box-sizing:border-box;margin:0;padding:0;}body{font-family:Arial,sans-serif;}'
