    +'.hl{font-size:11px;line-height:1.9;} .hl strong{font-size:13px;display:block;margin-bottom:2px;}'
    +'.hc img{width:58px;height:58px;object-fit:contain;}'
    +'.hr{text-align:right;font-size:11px;line-height:1.8;}'
    +'table{width:100%;border-collapse:collapse;}'
    +'.footer{text-align:center;padding:10px;font-size:11px;color:#555;border-top:1px solid #ccc;}'
    +'@media print{body{margin:0;}.page{width:100%;padding:8mm;}@page{size:A4 portrait;margin:10mm;}}'
    +'</style></head><body>'
    +'<div class="page"><div class="box">'
