/* ===== EFFECT DIAGNOSIS STATE ===== */
var effState = {
  types: [],
  typeIndex: 0,
  stepIndex: 0,
  selectedOpts: {},
  scores: {},
  stepResults: []
};

function startEffectDiagnosis(){
  var confirmedTypes = [];
  diagStepOrder.forEach(function(type){
    var res = diagAllResults[type];
    var ev  = evaluateDiagnosis(type, res ? res.keys : []);
    if(ev.level === 'confirmed' || ev.level === 'probable'){
      confirmedTypes.push(type);
    }
  });
  if(confirmedTypes.length === 0){
    closeResult();
    return;
  }
  effState.types      = confirmedTypes;
  effState.typeIndex  = 0;
  effState.stepIndex  = 0;
  effState.selectedOpts = {};
  effState.scores     = {};
  effState.stepResults= [];
  effState._onGuidelinePage = false;
  _effGuidelineSeen   = {};
  confirmedTypes.forEach(function(t){ effState.scores[t] = 0; });
  renderEffectStep();
  document.getElementById('effectOverlay').classList.add('open');
  document.getElementById('effectOverlay').scrollTop = 0;
  document.body.style.overflow = 'hidden';
}

/* গাইডলাইন দেখা হয়েছে কিনা ট্র্যাক */
var _effGuidelineSeen = {};

function showEffectGuideline(){
  var type  = effState.types[effState.typeIndex];
  var eData = effectData[type];
  if(!eData) return;
  var body = document.getElementById('effectBody');
  var html = '';
  html += '<div style="margin-bottom:10px;">';
  html += eData.guideline || '';
  html += '</div>';
  html += '<div style="background:#e8f5eb;border-radius:8px;padding:10px 12px;margin-bottom:8px;font-size:12px;color:#1a5c3a;line-height:1.7;">';
  html += '&#x2705; গাইডলাইন পড়া শেষ হলে নিচের বাটনে চাপুন এবং ডায়াগনোসিস শুরু করুন।';
  html += '</div>';
  if(body) body.innerHTML = html;
  _effGuidelineSeen[type] = true;
  var nextBtn = document.getElementById('effectNextBtn');
  if(nextBtn) nextBtn.innerHTML = '<i class="fas fa-play-circle"></i> ডায়াগনোসিস শুরু করুন';
  var skipBtn = document.querySelector('.effect-skip-btn');
  if(skipBtn) skipBtn.style.display = 'none';
  effState._onGuidelinePage = true;
}

function renderEffectStep(){
  var type  = effState.types[effState.typeIndex];
  var eData = effectData[type];
  if(!eData){ effNextType(); return; }
  var steps = eData.steps;
  var si    = effState.stepIndex;
  if(si >= steps.length){ effNextType(); return; }
  var step  = steps[si];
  var header = document.getElementById('effectHeader');
  var hTitle = document.getElementById('effectHeaderTitle');
  var hSub   = document.getElementById('effectHeaderSub');
  var hIcon  = document.getElementById('effectHeaderIcon');
  var stepBar= document.getElementById('effectStepBar');
  if(header){ header.style.background = eData.color; stepBar.style.background = eData.color; }
  if(hIcon)  hIcon.innerHTML  = eData.icon;
  if(hTitle) hTitle.textContent = eData.label + ' — ইফেক্ট ডায়াগনোসিস';

  /* গাইডলাইন পেজ — প্রতিটি রোগের প্রথম ধাপে একবার */
  if(!_effGuidelineSeen[type] && eData.guideline){
    if(hSub) hSub.textContent = 'শুরু করার আগে গাইডলাইন পড়ুন';
    if(stepBar){
      var gDots = '';
      for(var gi=0;gi<steps.length;gi++) gDots += '<div class="effect-step-dot"></div>';
      stepBar.innerHTML = gDots;
    }
    showEffectGuideline();
    return;
  }
  effState._onGuidelinePage = false;
  var skipBtn = document.querySelector('.effect-skip-btn');
  if(skipBtn) skipBtn.style.display = '';

  if(hSub) hSub.textContent = (step.layerLabel || ('ধাপ '+(si+1)+'/'+steps.length)) + ' — ইফেক্ট নির্বাচন করুন';
  if(stepBar){
    var dots = '';
    for(var i=0;i<steps.length;i++){
      var cls = i < si ? 'done' : i === si ? 'active' : '';
      dots += '<div class="effect-step-dot '+cls+'"></div>';
    }
    stepBar.innerHTML = dots;
  }

  var body = document.getElementById('effectBody');
  var html = '';

  /* স্তর ব্যাজ */
  if(step.layerLabel){
    html += '<div style="background:'+eData.color+';color:#fff;font-size:11px;font-weight:700;padding:5px 10px;border-radius:6px;margin-bottom:10px;display:inline-block;">'+step.layerLabel+'</div>';
  }

  /* আয়াত বক্স */
  html += '<div class="effect-ayat-box">';
  html += '<div class="effect-ayat-title">&#x1F4D6; '+step.ayat.ref+'</div>';
  html += '<div class="effect-ayat-arabic">'+step.ayat.arabic+'</div>';
  html += '<div class="effect-ayat-bangla">'+step.ayat.bangla+'</div>';
  html += '</div>';

  /* পড়ার নির্দেশ */
  html += '<div class="effect-count-box">';
  html += '<div class="effect-count-icon">&#x1F4FF;</div>';
  html += '<div><div class="effect-count-text">'+step.count+'</div>';
  html += '<div class="effect-count-sub">এই নির্দেশ অনুযায়ী পড়ুন, তারপর ইফেক্ট নির্বাচন করুন</div></div>';
  html += '</div>';

  /* বিস্তারিত নির্দেশনা */
  html += '<div class="effect-inst">&#x1F4CC; '+step.instruction+'</div>';

  /* প্রশ্ন */
  html += '<div class="effect-q">'+step.question+'</div>';
  html += '<div style="font-size:11px;color:#888;margin-bottom:8px;">&#x2714;&#xFE0F; একাধিক অপশন সিলেক্ট করতে পারবেন</div>';

  /* অপশনগুলো — মাল্টি-সিলেক্ট */
  effState.selectedOpts = {};
  step.options.forEach(function(opt, idx){
    var badge = opt.w >= 6 ? '<span class="effect-opt-badge" style="background:#8B0000;">সর্বোচ্চ</span>'
              : opt.w >= 4 ? '<span class="effect-opt-badge" style="background:#c0392b;">শক্তিশালী</span>'
              : opt.w >= 2 ? '<span class="effect-opt-badge" style="background:#e67e22;">মাঝারি</span>'
              : opt.w === 1 ? '<span class="effect-opt-badge" style="background:#27ae60;">দুর্বল</span>'
              : '<span class="effect-opt-badge" style="background:#7f8c8d;">নিরপেক্ষ</span>';
    html += '<div class="effect-opt" id="eopt'+idx+'" onclick="toggleEffOpt('+idx+','+opt.w+',\''+opt.type+'\')">';
    html += '<div class="effect-opt-dot" id="eoptd'+idx+'"></div>';
    html += '<div class="effect-opt-label">'+opt.text+badge+'</div>';
    html += '</div>';
  });

  if(body) body.innerHTML = html;

  /* পরবর্তী বাটন লেবেল */
  var nextBtn = document.getElementById('effectNextBtn');
  var totalSteps = 0;
  effState.types.forEach(function(t){ totalSteps += (effectData[t]?effectData[t].steps.length:0); });
  var doneSteps = 0;
  for(var ti=0;ti<effState.typeIndex;ti++){
    doneSteps += (effectData[effState.types[ti]]?effectData[effState.types[ti]].steps.length:0);
  }
  doneSteps += si;
  var isLast = (doneSteps >= totalSteps - 1);
  if(nextBtn){
    nextBtn.innerHTML = isLast
      ? '<i class="fas fa-check-circle"></i> ইফেক্ট ডায়াগনোসিস সম্পন্ন'
      : '<i class="fas fa-arrow-right"></i> পরবর্তী ধাপ';
  }
}

var _effStepScore = 0;
var _effStepType  = '';

function toggleEffOpt(idx, w, type){
  var el  = document.getElementById('eopt'+idx);
  var dot = document.getElementById('eoptd'+idx);
  if(!el) return;
  /* neg অপশন সিলেক্ট হলে সব pos বাতিল করে শুধু neg রাখো */
  if(type === 'neg'){
    if(el.classList.contains('sel-neg')){
      el.classList.remove('sel-neg');
      if(dot) dot.innerHTML = '';
      delete effState.selectedOpts[idx];
    } else {
      /* সব pos বাতিল */
      Object.keys(effState.selectedOpts).forEach(function(k){
        var oel = document.getElementById('eopt'+k);
        var odb = document.getElementById('eoptd'+k);
        if(oel){ oel.classList.remove('sel','sel-neg'); }
        if(odb){ odb.innerHTML = ''; }
      });
      effState.selectedOpts = {};
      el.classList.add('sel-neg');
      if(dot) dot.innerHTML = '&#x2714;';
      effState.selectedOpts[idx] = {w:w, type:'neg'};
    }
    return;
  }
  /* pos অপশন — মাল্টি-সিলেক্ট, কিন্তু neg বাতিল করো */
  Object.keys(effState.selectedOpts).forEach(function(k){
    if(effState.selectedOpts[k].type === 'neg'){
      var nel = document.getElementById('eopt'+k);
      var ndb = document.getElementById('eoptd'+k);
      if(nel){ nel.classList.remove('sel-neg'); }
      if(ndb){ ndb.innerHTML = ''; }
      delete effState.selectedOpts[k];
    }
  });
  if(el.classList.contains('sel')){
    el.classList.remove('sel');
    if(dot) dot.innerHTML = '';
    delete effState.selectedOpts[idx];
  } else {
    el.classList.add('sel');
    if(dot) dot.innerHTML = '&#x2714;';
    effState.selectedOpts[idx] = {w:w, type:'pos'};
  }
  updateEffCount();
}

function updateEffCount(){
  var cnt = Object.keys(effState.selectedOpts).filter(function(k){
    return effState.selectedOpts[k].type === 'pos';
  }).length;
  /* বাটন লেবেলে count দেখাও */
  var nextBtn = document.getElementById('effectNextBtn');
  if(nextBtn && cnt > 0 && !effState._onGuidelinePage){
    var cur = nextBtn.innerHTML;
    if(cur.indexOf('সম্পন্ন') === -1){
      /* count badge */
    }
  }
}

function effectNext(){
  /* গাইডলাইন পেজে থাকলে ডায়াগনোসিসে যাও */
  if(effState._onGuidelinePage){
    effState._onGuidelinePage = false;
    renderEffectStep();
    document.getElementById('effectOverlay').scrollTop = 0;
    return;
  }
  /* কোনো অপশন না বাছলে সতর্কতা */
  var keys = Object.keys(effState.selectedOpts);
  if(keys.length === 0){ alert('অন্তত একটি অপশন নির্বাচন করুন।'); return; }
  var type = effState.types[effState.typeIndex];
  /* স্কোর যোগ করো */
  keys.forEach(function(k){
    var opt = effState.selectedOpts[k];
    if(opt.type === 'pos') effState.scores[type] = (effState.scores[type]||0) + opt.w;
  });
  effState.stepResults.push({type:type, step:effState.stepIndex, opts:effState.selectedOpts});
  effState.stepIndex++;
  effState.selectedOpts = {};
  var steps = (effectData[type]||{steps:[]}).steps;
  if(effState.stepIndex >= steps.length){
    effNextType();
  } else {
    renderEffectStep();
    document.getElementById('effectOverlay').scrollTop = 0;
  }
}

function effectSkip(){
  if(effState._onGuidelinePage){
    effState._onGuidelinePage = false;
    _effGuidelineSeen[effState.types[effState.typeIndex]] = true;
    renderEffectStep();
    document.getElementById('effectOverlay').scrollTop = 0;
    return;
  }
  var type = effState.types[effState.typeIndex];
  effState.stepResults.push({type:type, step:effState.stepIndex, opts:{skip:true}});
  effState.stepIndex++;
  var steps = (effectData[type]||{steps:[]}).steps;
  if(effState.stepIndex >= steps.length){
    effNextType();
  } else {
    renderEffectStep();
    document.getElementById('effectOverlay').scrollTop = 0;
  }
}

function effNextType(){
  effState.typeIndex++;
  effState.stepIndex = 0;
  if(effState.typeIndex >= effState.types.length){
    closeEffectDiag();
    showEffectResult();
    return;
  }
  renderEffectStep();
  document.getElementById('effectOverlay').scrollTop = 0;
}

function closeEffectDiag(){
  document.getElementById('effectOverlay').classList.remove('open');
  document.body.style.overflow = '';
}

function showEffectResult(){
  var info = diagPatientInfo;
  var today = new Date();
  var dateStr = String(today.getDate()).padStart(2,'0')+'.'+String(today.getMonth()+1).padStart(2,'0')+'.'+String(today.getFullYear()).slice(2);
  var diagColors3 = {bodnazar:'#5c3a1a', jadu:'#2d1a5c', jinn:'#1a3a5c', waswasa:'#4a1a5c', bachcha:'#1a5c4a'};
  var maxScores = {bodnazar:54, jadu:72, jinn:66, waswasa:60, bachcha:42};
  var sub = document.getElementById('effResultSub');
  if(sub) sub.textContent = info.name + ' | ' + dateStr;
  var body = document.getElementById('effResultBody');
  var html = '';
  /* ─── গুরুত্বপূর্ণ সতর্কতা ─── */
  html += '<div style="background:#fff3e0;border:1.5px solid #ff9800;border-radius:10px;padding:10px 13px;margin-bottom:12px;">';
  html += '<div style="font-size:11px;font-weight:700;color:#e65100;margin-bottom:5px;">&#x26A0;&#xFE0F; জরুরি জ্ঞাতব্য</div>';
  html += '<div style="font-size:11px;color:#444;line-height:1.7;">• প্রতিক্রিয়া না হওয়া মানেই সমস্যা নেই — এমন নয়। শক্তিশালী জিন, অধিক গুনাহ বা ওষুধের প্রভাবে প্রতিক্রিয়া কম হতে পারে।<br>• প্রতিক্রিয়া হলেই নিশ্চিত নয় — কিছু প্রতিক্রিয়া মনস্তাত্ত্বিকও হতে পারে।<br>• <strong>চূড়ান্ত নিশ্চিতকরণের জন্য একজন অভিজ্ঞ রাকির সাথে সশরীরে সেশন করুন।</strong></div>';
  html += '</div>';
  html += '<div style="background:#e8f5eb;border:1px solid #b2dbb9;border-radius:10px;padding:12px 14px;margin-bottom:12px;">';
  html += '<div style="font-size:12px;font-weight:700;color:#1a5c3a;text-transform:uppercase;margin-bottom:8px;">&#x1F4CA; ইফেক্ট স্কোর বিশ্লেষণ</div>';
  var fullMsg = '&#x1F3AF; *ইফেক্ট ডায়াগনোসিস রিপোর্ট*\n';
  fullMsg += '&#x1F464; নাম: *'+info.name+'*\n';
  fullMsg += '&#x1F4C5; তারিখ: '+dateStr+'\n';
  fullMsg += '━━━━━━━━━━━━━━━━━━━━\n\n';
  effState.types.forEach(function(type){
    var score   = effState.scores[type] || 0;
    var maxS    = maxScores[type] || 20;
    var pct     = Math.min(100, Math.round((score/maxS)*100));
    var color   = diagColors3[type]||'#1a5c3a';
    var eData   = effectData[type];
    var label   = eData ? eData.label : type;
    var icon    = eData ? eData.icon : '';
    var level, levelLabel, levelColor, advice;
    if(pct >= 70){
      level='high'; levelLabel='&#x1F534; উচ্চ নিশ্চিততা ('+pct+'%)'; levelColor='#c0392b';
      advice='ইফেক্ট ডায়াগনোসিসে শক্তিশালী প্রতিক্রিয়া পাওয়া গেছে। সিম্পটম ডায়াগনোসিসের ফলাফল নিশ্চিত হয়েছে।';
    } else if(pct >= 40){
      level='medium'; levelLabel='&#x1F7E1; মাঝারি নিশ্চিততা ('+pct+'%)'; levelColor='#e67e22';
      advice='কিছু প্রতিক্রিয়া পাওয়া গেছে। সম্ভাবনা আছে তবে আরও রুকইয়াহ ও পর্যবেক্ষণ প্রয়োজন।';
    } else if(pct >= 15){
      level='low'; levelLabel='&#x1F535; দুর্বল সংকেত ('+pct+'%)'; levelColor='#2980b9';
      advice='সামান্য প্রতিক্রিয়া পাওয়া গেছে। এই মুহূর্তে নিশ্চিত বলা কঠিন।';
    } else {
      level='none'; levelLabel='&#x26AA; প্রতিক্রিয়া নেই ('+pct+'%)'; levelColor='#7f8c8d';
      advice='ইফেক্ট ডায়াগনোসিসে বিশেষ প্রতিক্রিয়া পাওয়া যায়নি।';
    }
    var barW = Math.max(2, pct);
    var barC = pct >= 70 ? '#c0392b' : pct >= 40 ? '#e67e22' : pct >= 15 ? '#2980b9' : '#95a5a6';
    html += '<div style="margin-bottom:10px;">';
    html += '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">';
    html += '<span style="font-size:13px;font-weight:700;color:'+color+';">'+icon+' '+label+'</span>';
    html += '<span style="font-size:11px;font-weight:700;color:'+levelColor+';">'+levelLabel+'</span>';
    html += '</div>';
    html += '<div style="background:#e0e0e0;border-radius:5px;height:10px;overflow:hidden;margin-bottom:4px;">';
    html += '<div style="background:'+barC+';width:'+barW+'%;height:100%;border-radius:5px;transition:width 0.5s;"></div>';
    html += '</div>';
    html += '<div style="font-size:11px;color:#555;">'+advice+'</div>';
    html += '</div>';
    fullMsg += icon+' *'+label+'* — '+levelLabel+'\n'+advice+'\n\n';
  });
  html += '</div>';
  html += '<div style="background:#fff8e1;border:1px solid #f9a825;border-radius:10px;padding:12px 14px;margin-bottom:12px;">';
  html += '<div style="font-size:12px;font-weight:700;color:#e65100;text-transform:uppercase;margin-bottom:8px;">&#x1F4CB; সম্মিলিত বিশ্লেষণ</div>';
  var highCount = effState.types.filter(function(t){
    var s = effState.scores[t]||0;
    var m = maxScores[t]||20;
    return (s/m) >= 0.70;
  }).length;
  var medCount = effState.types.filter(function(t){
    var s = effState.scores[t]||0;
    var m = maxScores[t]||20;
    var p = s/m;
    return p >= 0.40 && p < 0.70;
  }).length;
  var summaryHtml = '';
  if(highCount > 0){
    summaryHtml = '<div style="font-size:13px;color:#c0392b;font-weight:700;margin-bottom:6px;">&#x26A1; ইফেক্ট ডায়াগনোসিস নিশ্চিত করেছে!</div>';
    summaryHtml += '<div style="font-size:12px;color:#333;line-height:1.7;">'+highCount+'টি রোগে শক্তিশালী ইফেক্ট পাওয়া গেছে। সিম্পটম ডায়াগনোসিসের ফলাফল এখন উচ্চ নিশ্চিততায় প্রমাণিত। দ্রুত একজন অভিজ্ঞ রাকির সাথে সশরীরে যোগাযোগ করুন।</div>';
  } else if(medCount > 0){
    summaryHtml = '<div style="font-size:13px;color:#e67e22;font-weight:700;margin-bottom:6px;">&#x1F7E1; মাঝারি সম্ভাবনা নিশ্চিত</div>';
    summaryHtml += '<div style="font-size:12px;color:#333;line-height:1.7;">কিছু প্রতিক্রিয়া পাওয়া গেছে। নিয়মিত রুকইয়াহ শুরু করুন এবং ১ সপ্তাহ পর পুনরায় ডায়াগনোসিস করুন।</div>';
  } else {
    summaryHtml = '<div style="font-size:13px;color:#2980b9;font-weight:700;margin-bottom:6px;">&#x1F535; সতর্কতার সাথে পর্যবেক্ষণ করুন</div>';
    summaryHtml += '<div style="font-size:12px;color:#333;line-height:1.7;">ইফেক্ট ডায়াগনোসিসে বিশেষ প্রতিক্রিয়া পাওয়া যায়নি। নিয়মিত আযকার ও ইবাদত অব্যাহত রাখুন। সমস্যা থাকলে একজন রাকির পরামর্শ নিন।</div>';
  }
  html += summaryHtml;
  html += '</div>';
  fullMsg += '━━━━━━━━━━━━━━━━━━━━\n';
  fullMsg += '&#x1F932; اللهم اشفه وعافه — আল্লাহুম্মাশফিহি ওয়া আফিহি।';
  html += '<button class="result-wa-btn" onclick="sendEffResultWA(this)" data-msg="'+encodeURIComponent(fullMsg)+'" style="width:100%;padding:13px;background:#25D366;color:#fff;border:none;border-radius:9px;font-size:15px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;font-family:Arial,sans-serif;"><i class="fab fa-whatsapp"></i> রিপোর্ট WhatsApp-এ পাঠাও</button>';
  html += '<button onclick="closeEffResult()" style="width:100%;padding:9px;background:none;color:#888;border:1px solid #ddd;border-radius:9px;font-size:13px;cursor:pointer;margin-top:8px;font-family:Arial,sans-serif;">বন্ধ করুন</button>';
  if(body) body.innerHTML = html;
  document.getElementById('effResultOverlay').classList.add('open');
  document.getElementById('effResultOverlay').scrollTop = 0;
  document.body.style.overflow = 'hidden';
}

function sendEffResultWA(btn){
  var encoded = btn.getAttribute('data-msg');
  var m = decodeURIComponent(encoded);
  window.open('https://api.whatsapp.com/send?phone='+getWAPhone()+'&text='+encodeURIComponent(m),'_blank');
}

function closeEffResult(){
  document.getElementById('effResultOverlay').classList.remove('open');
  document.body.style.overflow = '';
}

